def get_demo(txt):
  m=re.search(r'Demo pair \d+ input \(\d+x\d+\):\n(.*?)\nDemo pair \d+ output \(\d+x\d+\):\n(.*?)(?:\n\nSame instance|\Z)',txt,re.S)
  return ([[int(x) for x in line.split()] for line in m.group(1).splitlines()], [[int(x) for x in line.split()] for line in m.group(2).splitlines()])
